*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수


scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gDtecDd;
scwin.gSeq;
scwin.gChgStatCd;
scwin.regMode; // 'REG', 'MOD'
scwin.gComAbbrv;
scwin.gChgTpNm;
scwin.gStrtDd;
scwin.gChgRsnNm;
scwin.gMisc;
scwin.vScrenID = 'ULDSTF71002.xml';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    //조회일자 오늘로 셋팅
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

};
scwin.fn_Search = function() {
    var vISU_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vSTRT_DT = $c.stf.getObjectValue(edt_FromDate);
    var vEND_DT = $c.stf.getObjectValue(edt_ToDate);
    var vADVCE_COM_PROCS_STAT_CD = $c.stf.getObjectValue(cmb_stat_cd);
    var url = "/digital//Digitalissueinfo.do?method=listDigitalDesignAdviceApplProcs";
    url += "&ISU_CD=" + vISU_CD;
    url += "&ADVCE_COM_PROCS_STAT_CD=" + $c.stf.trim(vADVCE_COM_PROCS_STAT_CD);
    url += "&STRT_DT=" + vSTRT_DT;
    url += "&END_DT=" + vEND_DT;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};

/********************************************** 
 * 함수명 : fn_GetParIsur(), fn_SetParIsur()
 * 설명    : 종목명 호출관련
 ***********************************************/
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = $c.stf.getObjectValue(txb_isur_cd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_com_abbrv); // 명칭값을 포함할 컨트롤
    //arrPar[2] = fr_SecuGrpId;	  					  // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_isur_cd.setValue(arrPar[0].ISU_CD);
        txb_com_abbrv.setValue(arrPar[0].ISU_KOR_NM);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    gSEQ = dts_List.getCellData(eval(row), "SEQ");
    gDESIGN_ADVSER_ISUR_CD = dts_List.getCellData(eval(row), "DESIGN_ADVSER_ISUR_CD");
    gDESIGN_ADVSER_COM_ABBRV = dts_List.getCellData(eval(row), "DESIGN_ADVSER_COM_ABBRV");
    gADVCE_COM_ISUR_CD = dts_List.getCellData(eval(row), "ADVCE_ISU_CD");
    gADVCE_COM_ABBRV = dts_List.getCellData(eval(row), "ADVCE_COM_ABBRV");
    gADVCE_COM_APPL_TP_NM = dts_List.getCellData(eval(row), "ADVCE_COM_APPL_TP_NM");
    gADVCE_COM_APPL_TP_CD = dts_List.getCellData(eval(row), "ADVCE_ISU_APPL_TP_CD");
    gSTRT_DD = dts_List.getCellData(eval(row), "STRT_DD");
    gAPPL_REQ_DD = dts_List.getCellData(eval(row), "APPL_REQ_DD");
    gAPPL_DDTM = dts_List.getCellData(eval(row), "APPL_DDTM");
    gADVCE_COM_PROCS_STAT_NM = dts_List.getCellData(eval(row), "ADVCE_COM_PROCS_STAT_NM");
    gADVCE_COM_PROCS_STAT_CD = dts_List.getCellData(eval(row), "ADVCE_ISU_PROCS_STAT_CD");
    gCONTRT_DD = dts_List.getCellData(eval(row), "CONTRT_DD");
    gRELEAS_DD = dts_List.getCellData(eval(row), "RELEAS_DD");
    gREVWR_NM = dts_List.getCellData(eval(row), "REVWR_NM");
    gREVW_DDTM = dts_List.getCellData(eval(row), "REVW_DDTM");
    gAPPROVR_NM = dts_List.getCellData(eval(row), "APPROVR_NM");
    gAPPROV_DDTM = dts_List.getCellData(eval(row), "APPROV_DDTM");
    gEMP_NM = dts_List.getCellData(eval(row), "EMP_NM");
    gDEP_NM = dts_List.getCellData(eval(row), "DEP_NM");
    if (colid == "ADVCE_COM_PROCS_STAT_NM") {
        // 승인상태 클릭 시
        var url = "/issueinfo/ULDSTF71002_P.gfm";
        var winTitle = "지정자문인 자문종목 지정(해제)";
        await $c.frame.CreateDialogFrame("ULDSTF71002_P", url, winTitle, 100, 100, 725, 300, "window");
    }
};
scwin.img_com_srch_onclick = function() {
    //IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lcd.fn_PopFindDigitalIsuAll();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (dts_List.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_Grid, "지정자문인 담당종목 변경처리 현황", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_Search();
};
scwin.txb_isur_cd_onchange = function() {
    $c.stf.setObjectValue(txb_com_abbrv, "");
};
